/// <summary>
/// Extension of CustParameters form for MPJ_21275_BackOrders
/// </summary>
[ExtensionOf(formDatasourceStr(CustParameters, CustParameters))]
final class METCustParametersForm_Extension
{
}

Method.Source:
   /// <summary>
   /// Depends on legal entity allow back orders parameters is active or inactive
   /// </summary>
    public void init()
    {
        FormRun             formRun             = this.formRun(); 
        FormCheckBoxControl metAllowBackOrders  = formRun.design().controlName(formControlStr(CustParameters, METBackOrdersGroup_METAllowBackOrders)) as FormCheckBoxControl;
        
        next init();

        CustParameters custParameters = CustParameters::find(); 
       
        metAllowBackOrders.visible(isSystemAdministrator());
        
        custParameters.updateBackOrderParameter();
    }
